function applyPane(p){
  const nav=document.getElementById("mtabs");
  [...nav.children].forEach(x=>x.classList.toggle("on",x.dataset.p===p));
  ["1","2","3","4"].forEach(k=>{
    const el=document.getElementById("pane"+k);
    if(el) el.style.display=(k===p)?"":"none";
  });
  setTimeout(()=>{
    if(chart) chart.resize();
    if(vchart) vchart.resize();
    if(p==="2") renderVChart();
    if(p==="3") renderSentiChart();
    if(p==="4") renderUSChart();
  },0);
}
document.getElementById("mtabs").addEventListener("click",e=>{
  const b=e.target.closest("button"); if(!b)return;
  applyPane(b.dataset.p);
});

