const updBtn=document.getElementById("updBtn");
const updTxt=document.getElementById("updTxt");
const updSt=document.getElementById("updSt");
function setStatus(m){ updSt.textContent=m; }

/* 版本角标：排查「改了没生效」时的第一现场证据。
   页面是通过 http 还是 file 打开、服务里跑的是哪一份代码，都能和它对上。 */
(function verBadge(){
  const el=document.getElementById("verBadge");
  if(!el) return;
  el.textContent = VER ? "v"+VER : "v—";
  el.title = "版本 " + (VER||"未知") + "\n构建于 " + (BUILT||"未知")
           + "\n数据口径以 CHANGELOG 对应版本为准";
})();

/* 统一 POST：把 HTTP 状态码、服务端 error 文本、超时都还原成人话。
   之前的写法 r.json() 一旦失败就抛 "Unexpected token"，真实原因被吞掉。 */
async function postJSON(url, ms=240000){
  const ac=new AbortController();
  const tid=setTimeout(()=>ac.abort(), ms);
  try{
    const r=await fetch(url,{method:"POST",signal:ac.signal});
    const txt=await r.text();
    let j=null;
    try{ j=JSON.parse(txt); }
    catch(_){ throw new Error(`服务返回非 JSON（HTTP ${r.status}）：${txt.slice(0,160)||"空响应"}`); }
    if(!r.ok || !j.ok) throw new Error(j.error || `HTTP ${r.status}`);
    return j;
  }catch(e){
    if(e && e.name==="AbortError") throw new Error(`请求超时（${Math.round(ms/1000)}s 未返回）`);
    if(e instanceof TypeError) throw new Error("连不上本地服务（127.0.0.1:8765 未启动或已退出）");
    throw e;
  }finally{
    clearTimeout(tid);
  }
}

async function doRefresh(){
  if(location.protocol==="file:"){
    setStatus("❌ 当前是双击文件打开的（file://），无法调用更新接口。请访问 http://127.0.0.1:8765/");
    return;
  }
  updBtn.disabled=true; updBtn.classList.add("busy");
  updTxt.textContent="取数中…"; setStatus("正在从腾讯拉取最新日线…");
  try{
    const j=await postJSON("/api/refresh");
    DATA=j.data;
    if(j.val) VAL=j.val;
    updTxt.textContent="更新数据";
    try{
      renderAll();
      setStatus("✅ 已更新 "+j.updated+"（耗时 "+j.elapsed+"s）");
    }catch(re){
      // 取数成功但渲染出错时，不要把渲染异常说成“更新失败”
      setStatus("⚠ 数据已更新 "+j.updated+"，但页面渲染报错："+re.message);
    }
  }catch(err){
    setStatus("❌ 更新失败："+(err && err.message ? err.message : err));
    updTxt.textContent="更新数据";
  }finally{
    updBtn.disabled=false; updBtn.classList.remove("busy");
  }
}
updBtn.addEventListener("click",doRefresh);

