(async function init(){
  if(location.protocol==="file:"){
    const w=document.getElementById("protoWarn");
    if(w) w.style.display="";
    setStatus("⚠ 未连接本地服务，当前是静态数据，按钮不可用");
    return;
  }
  try{
    const r=await fetch("/api/data",{cache:"no-store"});
    const j=await r.json();
    if(j.ok){
      if(j.data) DATA=j.data;
      if(j.val) VAL=j.val;
      renderAll();
      setStatus(j.updated?("已更新 "+j.updated+"，可再点此更新"):"服务已连接，可点此更新");
    }
  }catch(e){
    setStatus("⚠ 连不上本地服务（127.0.0.1:8765），请确认 start-dashboard.bat 仍在运行");
  }
  try{
    const r=await fetch("/api/sentiment",{cache:"no-store"});
    const j=await r.json();
    if(j.ok && j.senti){ SEN=j.senti; renderSenti(); }
  }catch(e){ /* 情绪复盘不可用时保留构建期内嵌数据 */ }
  try{
    const r=await fetch("/api/us_senti",{cache:"no-store"});
    const j=await r.json();
    if(j.ok && j.us){ USS=j.us; renderUS(); }
  }catch(e){ /* 美股精灵不可用时保留构建期内嵌数据 */ }
})();

